# [SAME-SCENARIO] partial_results.py\n# Utility to process incremental streaming results from IBM Watson STT WebSocket.\n# Handles interim and final transcript fragments, concatenates them, and notifies\n# a downstream consumer when a full utterance is recognized.\n\nimport json\nfrom typing import List, Callable, Any\n\nclass PartialResultProcessor:\n    def __init__(self, on_final: Callable[[str], None]):\n        """\n        on_final: callback invoked with the complete transcription of an utterance.\n        """\n        self.on_final = on_final\n        self.buffer = ''\n        self.active_hypothesis = ''\n        self.in_progress = False\n\n    def handle_chunk(self, chunk: str):\n        \"\"\"\n        Append a new transcript chunk (interim or final) to the internal state.\n        Emits a final utterance when Watson marks the result as `final`.\n        "\"\"\n        self.active_hypothesis += chunk\n        # Watson returns interim results without the `final` flag.\n        # Final results contain the `final` key set to True.\n        if isinstance(chunk, dict) and chunk.get('final'):\n            # Final result arrived\n            self.buffer += self.active_hypothesis\n            self.on_final(self.buffer)\n            self.buffer = ''\n            self.active_hypothesis = ''\n            self.in_progress = False\n        else:\n            # Interim results; do not emit yet.\n            self.in_progress = True\n\n    def process_json(self, json_payload: str):\n        \"\"\"Parse a WebSocket JSON payload and delegate to handle_chunk.\n\n        Expected payload formats:\n        - Interim: {\"results\": [{\"alternatives\": [{\"transcript\": \"hello\", \"confidence\": 0.9}]}]}\n        - Final:   {\"results\": [{\"alternatives\": [{\"transcript\": \"hello\", \"confidence\": 0.9}], \"final\": true}]}\n        "\"\"\n        data = json.loads(json_payload)\n        for result in data.get('results', []):\n            alternatives = result.get('alternatives', [])\n            if alternatives:\n                transcript = alternatives[0].get('transcript', '')\n                # Attach the flag if present\n                if result.get('final'):\n                    self.handle_chunk({'transcript': transcript, 'final': True})\n                else:\n                    self.handle_chunk({'transcript': transcript})\n            else:\n                # No alternatives - ignore\n                pass\n\n# Simple demo usage\nif __name__ == '__main__':\n    def final_cb(text: str):\n        print('--- Final utterance:', text, '---')\n    processor = PartialResultProcessor(final_cb)\n    sample_interim = '{\"results\": [{\"alternatives\": [{\"transcript\": \"hello\"}]}]}'\n    sample_final = '{\"results\": [{\"alternatives\": [{\"transcript\": \" world\"}], \"final\": true}]}'\n    processor.process_json(sample_interim)\n    processor.process_json(sample_final)\n